// Token propio (sin PKCE de Supabase: funciona en cualquier navegador
// o dispositivo). Vence en 60 minutos; un solo uso.
const crypto = require('crypto');
const b = $input.first().json.body || {};
const email = (b.email || '').trim().toLowerCase();
if (!email || email.indexOf('@') < 1) throw new Error('email requerido');
const token = crypto.randomBytes(16).toString('hex');
const expira = new Date(Date.now() + 60 * 60 * 1000).toISOString();
const lang = (b.lang || b.idioma) === 'en' ? 'en' : 'es';
return [{ json: { token, email, app: b.app || 'calculadora', lang, expira_en: expira, nombre: b.nombre || '' } }];

